int liczba = 0;
int jasnosc = 0;

// D2=a, D3=b, D4=c, D5=d
// D6=e, D7=f, D8=g

void Znak(int iNumer) {

  byte segmenty;

  switch (iNumer) {

    case 0: segmenty = 0b00111111; break;
    case 1: segmenty = 0b00000110; break;
    case 2: segmenty = 0b01011011; break;
    case 3: segmenty = 0b01001111; break;
    case 4: segmenty = 0b01100110; break;
    case 5: segmenty = 0b01101101; break;
    case 6: segmenty = 0b01111101; break;
    case 7: segmenty = 0b00000111; break;
    case 8: segmenty = 0b01111111; break;
    case 9: segmenty = 0b01101111; break;

    default: segmenty = 0b00000000; break;
  }

  // Segmenty a-f na D2-D7
  // Wspolna anoda - LOW zapala segment

  PORTD = (PORTD & 0b00000011) |
          ((~segmenty & 0b00111111) << 2);

  // Segment g na D8

  if (segmenty & 0b01000000) {
    PORTB &= 0b11111110;
  }
  else {
    PORTB |= 0b00000001;
  }
}

void setup() {

  // D2-D7 jako wyjscia
  DDRD |= 0b11111100;

  // D8, D10, D11 jako wyjscia
  DDRB |= 0b00001101;

  // Wylaczenie wyswietlaczy
  PORTB &= 0b11110011;

  delay(500);
}

void loop() {

  // Odczyt fotorezystora
  jasnosc = analogRead(A0);

  // Przeliczenie zakresu 0-1023 na 0-99
  liczba = map(jasnosc, 0, 1023, 0, 99);

  // Ograniczenie wyniku
  liczba = constrain(liczba, 0, 99);

  // Wylaczenie obu wyswietlaczy
  PORTB &= 0b11110011;

  // Wyswietlenie jednosci
  Znak(liczba % 10);

  // Wlaczenie pierwszego wyswietlacza D10
  PORTB |= 0b00000100;

  delay(3);

  // Wylaczenie wyswietlaczy
  PORTB &= 0b11110011;

  // Wyswietlenie dziesiatek
  Znak((liczba / 10) % 10);

  // Wlaczenie drugiego wyswietlacza D11
  PORTB |= 0b00001000;

  delay(3);
}
